css:
.concept-1{--s1-ink:#152a33;--s1-deep:#123b49;--s1-deep-2:#0d303c;--s1-teal:#2f6a74;--s1-mist:#eef5f5;--s1-line:#d8e3e5;--s1-muted:#526a73;color:var(--s1-ink);background:#fff;min-width:0}.concept-1 .s1-wrap{width:min(1180px,calc(100% - 64px));margin-inline:auto}.concept-1 .s1-head{height:80px;display:flex;align-items:center;justify-content:space-between;gap:24px}.concept-1 .s1-brand{display:inline-flex;align-items:center;gap:11px;color:var(--s1-ink);font-size:20px;font-weight:780;letter-spacing:-.035em;text-decoration:none;white-space:nowrap}.concept-1 .s1-symbol{position:relative;width:24px;height:24px;flex:0 0 auto;border-radius:6px;background:var(--s1-deep);box-shadow:0 5px 12px rgba(18,59,73,.18)}.concept-1 .s1-symbol::before{content:'';position:absolute;inset:5px;border:1px solid rgba(219,239,241,.78);border-radius:50%}.concept-1 .s1-symbol::after{content:'';position:absolute;right:5px;bottom:5px;width:5px;height:5px;border-radius:50%;background:#c6e0df}.concept-1 .s1-nav{display:flex;align-items:center;gap:27px}.concept-1 .s1-nav button{min-height:44px;border:0;background:transparent;color:#29424b;padding:8px 1px;font-size:14px;font-weight:650;letter-spacing:-.015em}.concept-1 .s1-nav button:not(.primary):hover{color:var(--s1-deep);text-decoration:underline;text-decoration-color:#9db9be;text-underline-offset:7px}.concept-1 .s1-nav .primary{min-height:46px;padding:9px 18px;border:1px solid var(--s1-deep);border-radius:7px;background:var(--s1-deep);color:#fff;box-shadow:0 7px 16px rgba(18,59,73,.15)}
.concept-1 .s1-hero{position:relative;min-height:500px;overflow:hidden;isolation:isolate;background:#253940}.concept-1 .s1-photo{position:absolute;inset:0;z-index:-2;width:100%;height:100%;object-fit:cover;object-position:center 51%;transition:transform .45s cubic-bezier(.22,.7,.25,1),object-position .45s ease}.concept-1 .s1-hero::before{content:'';position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(5,24,31,.88) 0%,rgba(5,24,31,.71) 32%,rgba(5,24,31,.25) 60%,rgba(5,24,31,.04) 100%),linear-gradient(0deg,rgba(5,24,31,.2),transparent 38%)}.concept-1 .s1-hero-copy{min-height:500px;display:flex;flex-direction:column;justify-content:center;padding:64px 0 92px;color:#fff}.concept-1 .s1-label{display:flex;align-items:center;gap:10px;margin-bottom:21px;color:#d8e9ea;font-size:13px;font-weight:680;letter-spacing:.025em}.concept-1 .s1-label::before{content:'';width:26px;height:1px;background:#9ec1c3}.concept-1 h1{max-width:9.5em;font-size:clamp(46px,4.8vw,67px);font-weight:760;line-height:1.13;letter-spacing:-.045em}.concept-1 .s1-hero-copy>p:last-child{max-width:32em;margin-top:25px;color:#edf5f5;font-size:16px;line-height:1.72;letter-spacing:-.012em}.concept-1 .s1-hero[data-purpose=facility] .s1-photo{transform:scale(1.025);object-position:47% 51%}.concept-1 .s1-hero[data-purpose=support] .s1-photo{transform:scale(1.018);object-position:54% 49%}
.concept-1 .s1-explorer{position:relative;z-index:1;margin-top:-42px;padding-bottom:6px}.concept-1 .s1-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:7px;border:1px solid rgba(217,229,231,.8);border-radius:12px;background:rgba(255,255,255,.97);box-shadow:0 16px 40px rgba(17,49,59,.14);backdrop-filter:blur(8px)}.concept-1 .s1-option{min-width:0;min-height:108px;display:grid;grid-template-columns:40px minmax(0,1fr);align-items:center;gap:15px;border:1px solid transparent;border-radius:8px;background:#fff;color:var(--s1-ink);padding:19px 21px;text-align:left;transition:background-color .2s ease,color .2s ease,border-color .2s ease,box-shadow .2s ease}.concept-1 .s1-option:hover{background:#f2f7f7;border-color:#d8e6e7}.concept-1 .s1-option[aria-pressed=true]{border-color:var(--s1-deep);background:var(--s1-deep);color:#fff;box-shadow:0 7px 18px rgba(18,59,73,.2)}.concept-1 .s1-option>span:last-child{min-width:0}.concept-1 .s1-option strong{display:block;font-size:20px;font-weight:740;line-height:1.35;letter-spacing:-.03em}.concept-1 .s1-option small{display:block;margin-top:5px;color:#637a82;font-size:13px;line-height:1.45}.concept-1 .s1-option[aria-pressed=true] small{color:#d4e5e7}.concept-1 .s1-icon{width:36px;height:36px;display:grid;place-items:center;border:1px solid #9ab0b6;border-radius:50%;color:#52717a}.concept-1 .s1-option[aria-pressed=true] .s1-icon{border-color:#83aab1;color:#d6e8e9}.concept-1 .s1-icon i{display:block;width:12px;height:12px;border:1.5px solid currentColor;border-radius:3px}.concept-1 .s1-option:nth-child(2) .s1-icon i{width:4px;height:13px;border:0;border-radius:1px;background:currentColor;box-shadow:6px 0 0 currentColor}.concept-1 .s1-option:nth-child(3) .s1-icon i{border-radius:50%;box-shadow:4px 0 0 -1px #fff}
.concept-1 .s1-detail{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:42px;padding:34px 2px 32px}.concept-1 .s1-detail-copy{min-width:0}.concept-1 .s1-detail-label{margin-bottom:8px;color:var(--s1-teal);font-size:12px;font-weight:750;letter-spacing:.025em}.concept-1 .s1-detail h2{margin-bottom:10px;font-size:30px;font-weight:720;line-height:1.28;letter-spacing:-.035em}.concept-1 .s1-detail-description{max-width:48em;color:var(--s1-muted);font-size:14px;line-height:1.72}.concept-1 .s1-review-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:18px 0 0;padding:0;list-style:none}.concept-1 .s1-review-list li{min-width:0;border:1px solid var(--s1-line);border-radius:7px;background:#f8fafb;padding:10px 12px;color:#5b7077;font-size:11px;line-height:1.45}.concept-1 .s1-review-list strong{display:block;margin-bottom:2px;color:#274952;font-size:12px;font-weight:740}.concept-1 .s1-actions{width:230px;display:flex;flex-direction:column;align-items:stretch;gap:9px}.concept-1 .s1-actions .primary{min-height:52px;border-color:var(--s1-deep);border-radius:7px;background:var(--s1-deep);padding-inline:20px;white-space:nowrap;box-shadow:0 8px 18px rgba(18,59,73,.16)}.concept-1 .s1-action-note{color:#536a72;font-size:11px;line-height:1.5;text-align:center}.concept-1 .s1-detail-copy.enter{animation:s1-detail .26s ease-out}@keyframes s1-detail{from{opacity:.55;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
.concept-1 .s1-footer{border-top:1px solid var(--s1-line);background:var(--s1-mist);padding:22px 0}.concept-1 .s1-footer .s1-wrap{display:grid;grid-template-columns:1.1fr 1fr;align-items:center;gap:44px}.concept-1 .s1-footer p{color:#536b73;font-size:12px;line-height:1.65}.concept-1 .s1-footer strong{display:block;margin-bottom:3px;color:var(--s1-deep);font-size:13px;font-weight:720}.concept-1 .s1-footer .restriction{color:#344e57}
@media(max-width:900px){.concept-1 .s1-wrap{width:min(100% - 40px,1180px)}.concept-1 .s1-nav{gap:16px}.concept-1 .s1-detail{gap:24px}.concept-1 .s1-option{padding-inline:15px}.concept-1 .s1-option strong{font-size:18px}}
@media(max-width:760px){.concept-1 .s1-wrap{width:calc(100% - 32px)}.concept-1 .s1-head{height:auto;min-height:108px;display:grid;grid-template-columns:1fr;align-content:center;gap:5px;padding:8px 0}.concept-1 .s1-brand{font-size:17px;gap:8px}.concept-1 .s1-symbol{width:20px;height:20px;border-radius:5px}.concept-1 .s1-nav{width:100%;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px}.concept-1 .s1-nav button,.concept-1 .s1-nav .primary{min-width:0;min-height:44px;display:flex;align-items:center;justify-content:center;padding:6px 2px;border-radius:5px;font-size:10.5px;line-height:1.15;white-space:nowrap}.concept-1 .s1-nav .primary{box-shadow:none}.concept-1 .s1-hero{min-height:382px}.concept-1 .s1-photo{object-position:68% center}.concept-1 .s1-hero::before{background:linear-gradient(90deg,rgba(5,24,31,.84),rgba(5,24,31,.46) 58%,rgba(5,24,31,.1)),linear-gradient(0deg,rgba(5,24,31,.3),transparent 42%)}.concept-1 .s1-hero-copy{min-height:382px;padding:42px 0 65px}.concept-1 .s1-label{margin-bottom:15px;font-size:11px}.concept-1 .s1-label::before{width:20px}.concept-1 h1{max-width:8.8em;font-size:clamp(35px,10.4vw,42px);line-height:1.16}.concept-1 .s1-hero-copy>p:last-child{max-width:22em;margin-top:18px;font-size:13px;line-height:1.65}.concept-1 .s1-explorer{margin-top:-25px;padding-bottom:0}.concept-1 .s1-choices{padding:5px;border-radius:9px;box-shadow:0 11px 26px rgba(17,49,59,.14)}.concept-1 .s1-option{min-height:94px;display:flex;flex-direction:column;justify-content:center;gap:8px;padding:10px 4px;text-align:center}.concept-1 .s1-option strong{font-size:13.5px;line-height:1.3}.concept-1 .s1-option small{display:none}.concept-1 .s1-icon{width:27px;height:27px}.concept-1 .s1-icon i{width:10px;height:10px}.concept-1 .s1-detail{display:block;padding:23px 0 24px}.concept-1 .s1-detail-label{font-size:11px}.concept-1 .s1-detail h2{margin-bottom:8px;font-size:23px}.concept-1 .s1-detail-description{font-size:12.5px;line-height:1.65}.concept-1 .s1-review-list{gap:5px;margin-top:14px}.concept-1 .s1-review-list li{padding:8px 7px;font-size:10px}.concept-1 .s1-review-list strong{font-size:11px}.concept-1 .s1-actions{width:100%;margin-top:17px;gap:7px}.concept-1 .s1-actions .primary{width:100%;min-height:48px}.concept-1 .s1-action-note{font-size:10.5px}.concept-1 .s1-footer{padding:17px 0}.concept-1 .s1-footer .s1-wrap{grid-template-columns:1fr;gap:10px}.concept-1 .s1-footer p,.concept-1 .s1-footer .restriction{font-size:10.5px;line-height:1.55}.concept-1 .s1-footer strong{font-size:12px}}
@media(max-width:390px){.concept-1 .s1-wrap{width:calc(100% - 28px)}.concept-1 .s1-nav button,.concept-1 .s1-nav .primary{font-size:10px}.concept-1 .s1-hero{min-height:368px}.concept-1 .s1-hero-copy{min-height:368px;padding-top:38px}.concept-1 h1{font-size:36px}.concept-1 .s1-review-list li{padding-inline:5px}}
@media(max-width:360px){.concept-1 .s1-wrap{width:calc(100% - 24px)}.concept-1 .s1-nav button,.concept-1 .s1-nav .primary{font-size:9.5px}.concept-1 h1{font-size:34px}.concept-1 .s1-hero-copy>p:last-child{font-size:12.5px}.concept-1 .s1-option strong{font-size:12.5px}.concept-1 .s1-review-list{grid-template-columns:1fr;gap:4px}.concept-1 .s1-review-list li{display:grid;grid-template-columns:54px 1fr;align-items:center;gap:5px;padding:6px 9px}.concept-1 .s1-review-list strong{margin:0}.concept-1 .s1-detail h2{font-size:22px}}
@media(prefers-reduced-motion:reduce){.concept-1 .s1-photo,.concept-1 .s1-option{transition:none}.concept-1 .s1-detail-copy.enter{animation:none}}
.concept-1 .s1-review-photo{display:block;width:100%;height:116px;object-fit:cover;object-position:center 52%;border-radius:7px}.concept-1 .s1-actions{width:244px}@media(max-width:760px){.concept-1 .s1-actions{width:100%;display:grid;grid-template-columns:112px minmax(0,1fr);gap:5px 12px;align-items:center}.concept-1 .s1-review-photo{grid-column:1;grid-row:1/span 2;height:94px;object-position:53% center}.concept-1 .s1-actions .primary{grid-column:2;font-size:13px;padding-inline:8px;white-space:normal}.concept-1 .s1-action-note{grid-column:2;text-align:left;font-size:10.5px;margin:0}}
/* s1-readability-audit */@media(max-width:760px){.concept-1 .s1-nav button,.concept-1 .s1-nav .primary{font-size:11px}.concept-1 .s1-footer p,.concept-1 .s1-footer .restriction{font-size:12px;line-height:1.6}.concept-1 .s1-review-list li{font-size:11px}.concept-1 .s1-review-list strong{font-size:11.5px}}@media(max-width:360px){.concept-1 .s1-nav button,.concept-1 .s1-nav .primary{font-size:10.5px}}
